-- ESQUEMA NUEVO AISLADO. Revisar antes de ejecutar; Oracle DDL confirma implicitamente.
WHENEVER SQLERROR EXIT SQL.SQLCODE
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"CATEGORIAS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Name" NVARCHAR2(80) NOT NULL,
    "Kind" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_CATEGORIAS" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_CATEGORIAS_Id_Kind" UNIQUE ("Id", "Kind"),
    CONSTRAINT "CK_CATEGORY_KIND" CHECK ("Kind" IN (0,1))
)';
END;
/


BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"USUARIOS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Username" NVARCHAR2(40) NOT NULL,
    "NormalizedName" NVARCHAR2(40) NOT NULL,
    "PasswordHash" NVARCHAR2(512) NOT NULL,
    "RecoveryHash" NVARCHAR2(512) NOT NULL,
    "SessionVersion" NVARCHAR2(32) NOT NULL,
    "Failures" NUMBER(10) NOT NULL,
    "Revision" NUMBER(19) NOT NULL,
    "LockedUntil" TIMESTAMP(7),
    "WarningPercent" NUMBER(28,8) NOT NULL,
    CONSTRAINT "PK_USUARIOS" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_USER_WARNING" CHECK ("WarningPercent" > 0 AND "WarningPercent" < 100)
)';
END;
/


BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"ESCENARIOS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Name" NVARCHAR2(100) NOT NULL,
    "Start" TIMESTAMP(7) NOT NULL,
    "Years" NUMBER(10) NOT NULL,
    "Capital" NUMBER(28,8) NOT NULL,
    "Income" NUMBER(28,8) NOT NULL,
    "Expense" NUMBER(28,8) NOT NULL,
    "IncomeChange" NUMBER(28,8) NOT NULL,
    "ExpenseChange" NUMBER(28,8) NOT NULL,
    "Inflation" NUMBER(28,8) NOT NULL,
    "AnnualReturn" NUMBER(28,8) NOT NULL,
    "Contribution" NUMBER(28,8),
    "ContributionChange" NUMBER(28,8) NOT NULL,
    "UserId" NUMBER(19) NOT NULL,
    "RequestKey" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK_ESCENARIOS" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_SCENARIO_INPUTS" CHECK ("Capital" BETWEEN -1000000000 AND 1000000000 AND "Income" BETWEEN 0 AND 1000000000 AND "Expense" BETWEEN 0 AND 1000000000 AND "IncomeChange" BETWEEN -100 AND 100 AND "ExpenseChange" BETWEEN -100 AND 100 AND "ContributionChange" BETWEEN -100 AND 100 AND "Inflation" > -100 AND "Inflation" <= 100 AND "AnnualReturn" > -100 AND "AnnualReturn" <= 100 AND ("Contribution" IS NULL OR "Contribution" BETWEEN 0 AND 1000000000)),
    CONSTRAINT "CK_SCENARIO_YEARS" CHECK ("Years" IN (1,3,5,10)),
    CONSTRAINT "FK_ESCENARIOS_USUARIOS_UserId" FOREIGN KEY ("UserId") REFERENCES "USUARIOS" ("Id")
)';
END;
/


BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"METAS_AHORRO" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Name" NVARCHAR2(120) NOT NULL,
    "Description" NVARCHAR2(500),
    "Target" NUMBER(19,2) NOT NULL,
    "Deadline" TIMESTAMP(7) NOT NULL,
    "UserId" NUMBER(19) NOT NULL,
    "RequestKey" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK_METAS_AHORRO" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_METAS_AHORRO_Id_UserId" UNIQUE ("Id", "UserId"),
    CONSTRAINT "CK_GOAL_TARGET" CHECK ("Target" > 0 AND "Target" <= 1000000000),
    CONSTRAINT "FK_METAS_AHORRO_USUARIOS_UserId" FOREIGN KEY ("UserId") REFERENCES "USUARIOS" ("Id")
)';
END;
/


BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"PRESUPUESTOS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "Month" NVARCHAR2(7) NOT NULL,
    "CategoryId" NUMBER(19),
    "Scope" NVARCHAR2(80) NOT NULL,
    "Amount" NUMBER(19,2) NOT NULL,
    "UserId" NUMBER(19) NOT NULL,
    "RequestKey" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK_PRESUPUESTOS" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_BUDGET_AMOUNT" CHECK ("Amount" > 0 AND "Amount" <= 1000000000),
    CONSTRAINT "FK_PRESUPUESTOS_CATEGORIAS_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "CATEGORIAS" ("Id"),
    CONSTRAINT "FK_PRESUPUESTOS_USUARIOS_UserId" FOREIGN KEY ("UserId") REFERENCES "USUARIOS" ("Id")
)';
END;
/


BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"MOVIMIENTOS" (
    "Id" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "CategoryId" NUMBER(19),
    "GoalId" NUMBER(19),
    "Kind" NUMBER(10) NOT NULL,
    "Amount" NUMBER(19,2) NOT NULL,
    "Date" TIMESTAMP(7) NOT NULL,
    "Description" NVARCHAR2(500),
    "UserId" NUMBER(19) NOT NULL,
    "RequestKey" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK_MOVIMIENTOS" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ENTRY_AMOUNT" CHECK ("Amount" > 0 AND "Amount" <= 1000000000),
    CONSTRAINT "CK_ENTRY_KIND" CHECK (("Kind" IN (0,1) AND "CategoryId" IS NOT NULL AND "GoalId" IS NULL) OR ("Kind" = 2 AND "CategoryId" IS NULL AND "GoalId" IS NOT NULL)),
    CONSTRAINT "FK_MOVIMIENTOS_CATEGORIAS_CategoryId_Kind" FOREIGN KEY ("CategoryId", "Kind") REFERENCES "CATEGORIAS" ("Id", "Kind"),
    CONSTRAINT "FK_MOVIMIENTOS_METAS_AHORRO_GoalId_UserId" FOREIGN KEY ("GoalId", "UserId") REFERENCES "METAS_AHORRO" ("Id", "UserId"),
    CONSTRAINT "FK_MOVIMIENTOS_USUARIOS_UserId" FOREIGN KEY ("UserId") REFERENCES "USUARIOS" ("Id")
)';
END;
/


CREATE UNIQUE INDEX "IX_CATEGORIAS_Kind_Name" ON "CATEGORIAS" ("Kind", "Name")/


CREATE UNIQUE INDEX "IX_ESCENARIOS_UserId_RequestKey" ON "ESCENARIOS" ("UserId", "RequestKey")/


CREATE UNIQUE INDEX "IX_METAS_AHORRO_UserId_RequestKey" ON "METAS_AHORRO" ("UserId", "RequestKey")/


CREATE INDEX "IX_MOVIMIENTOS_CategoryId_Kind" ON "MOVIMIENTOS" ("CategoryId", "Kind")/


CREATE INDEX "IX_MOVIMIENTOS_GoalId_UserId" ON "MOVIMIENTOS" ("GoalId", "UserId")/


CREATE INDEX "IX_MOVIMIENTOS_UserId_Date" ON "MOVIMIENTOS" ("UserId", "Date")/


CREATE UNIQUE INDEX "IX_MOVIMIENTOS_UserId_RequestKey" ON "MOVIMIENTOS" ("UserId", "RequestKey")/


CREATE INDEX "IX_PRESUPUESTOS_CategoryId" ON "PRESUPUESTOS" ("CategoryId")/


CREATE UNIQUE INDEX "IX_PRESUPUESTOS_UserId_Month_Scope" ON "PRESUPUESTOS" ("UserId", "Month", "Scope")/


CREATE UNIQUE INDEX "IX_PRESUPUESTOS_UserId_RequestKey" ON "PRESUPUESTOS" ("UserId", "RequestKey")/


CREATE UNIQUE INDEX "IX_USUARIOS_NormalizedName" ON "USUARIOS" ("NormalizedName")/




